<?php
require __DIR__.'/../config/auth.php';requireAdmin();require __DIR__.'/../config/db.php';require __DIR__.'/../config/layout.php';
$sectores=$pdo->query("SELECT * FROM sectores WHERE slug<>'gerencia' ORDER BY orden")->fetchAll();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['accion']??'')==='crear'){$n=trim($_POST['nombre']??'');$e=strtolower(trim($_POST['email']??''));$p=$_POST['password']??'';$r=$_POST['rol']??'operador';$sid=(int)($_POST['sector_id']??0);$st=$pdo->prepare('INSERT INTO usuarios(nombre,email,password,rol,activo) VALUES(?,?,?,?,1)');$st->execute([$n,$e,password_hash($p,PASSWORD_DEFAULT),$r]);$uid=$pdo->lastInsertId();if($r==='admin'){$pdo->prepare('INSERT INTO usuario_sector SELECT ?,id,1,1 FROM sectores')->execute([$uid]);}elseif($sid){$pdo->prepare('INSERT INTO usuario_sector VALUES(?,?,1,?)')->execute([$uid,$sid,$r==='supervisor'?1:0]);}$msg='Usuario creado.';}
$usuarios=$pdo->query("SELECT u.*,(SELECT s.nombre FROM usuario_sector us JOIN sectores s ON s.id=us.sector_id WHERE us.usuario_id=u.id ORDER BY us.puede_editar DESC,s.orden LIMIT 1) sector FROM usuarios u ORDER BY FIELD(u.rol,'admin','supervisor','operador'),u.nombre")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><link rel="stylesheet" href="../../style.css"></head><body><div class="app"><?php sidebar($pdo,'usuarios');?><main class="content"><header class="section-top"><div><p class="eyebrow">GERENCIA</p><h1>Usuarios y permisos</h1><p>Administración de accesos.</p></div></header><?php if($msg):?><div class="alert success"><?=$msg?></div><?php endif;?><div class="admin-layout"><section class="form-panel"><h2>Nuevo usuario</h2><form method="post" class="form-grid"><input type="hidden" name="accion" value="crear"><label>Nombre<input name="nombre" required></label><label>Correo<input type="email" name="email" required></label><label>Contraseña<input type="password" name="password" required></label><label>Rol<select name="rol"><option value="supervisor">Supervisor</option><option value="operador">Operador</option><option value="admin">Gerencia/Admin</option></select></label><label>Sector<select name="sector_id"><option value="0">Sin sector</option><?php foreach($sectores as $s):?><option value="<?=$s['id']?>"><?=htmlspecialchars($s['nombre'])?></option><?php endforeach;?></select></label><button class="btn primary">Crear</button></form></section><section class="table-panel"><h2>Usuarios</h2><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Rol</th><th>Sector</th><th>Estado</th></tr></thead><tbody><?php foreach($usuarios as $u):?><tr><td><strong><?=htmlspecialchars($u['nombre'])?></strong><small><?=htmlspecialchars($u['email'])?></small></td><td><?=htmlspecialchars($u['rol']==='admin'?'Gerencia':ucfirst($u['rol']))?></td><td><?=htmlspecialchars($u['rol']==='admin'?'Todos':($u['sector']??'Sin asignar'))?></td><td><?=$u['activo']?'Activo':'Inactivo'?></td></tr><?php endforeach;?></tbody></table></div></section></div></main></div></body></html>
